{"command": "cat > /prediction.json << 'JSONEOF'
{
    "vllm/model_executor/layers/rotary_embedding/mrope.py": {
        "_triton_mrope_forward": "@triton.jit\ndef _triton_mrope_forward(\n    q_ptr,\n    k_ptr,\n    cos,\n    sin,\n    num_tokens,\n    n_qh: tl.constexpr,\n    n_kh: tl.constexpr,\n    hd: tl.constexpr,\n    rd: tl.constexpr,\n    pad_n_qh: tl.constexpr,\n    pad_n_kh: tl.constexpr,\n    pad_hd: tl.constexpr,\n    mrope_section_t: tl.constexpr,\n    mrope_section_h: tl.constexpr,\n    mrope_section_w: tl.constexpr,\n    is_interleaved: tl.constexpr,\n):\n    \"\"\"Triton kernel for mRoPE (multimodal rotary position embedding).\n    \n    Supports both interleaved and non-interleaved layouts:\n    - Non-interleaved: [TTT...HHH...WWW] - sections are concatenated\n    - Interleaved: [THTHTH...WWW] - sections are interleaved with stride 3\n      (positions 0,3,6,... are T; 1,4,7,... are H; 2,5,8,... are W)\n    \"\"\"\n    pid = tl.program_id(0)\n    # locate start address\n    q_ptr = q_ptr + pid * (n_qh * hd)\n    k_ptr = k_ptr + pid * (n_kh * hd)\n\n    # ####################################################################\n    # get the cos(mθ_{i...d/2}) and sin(mθ_{i...d/2}) for token position\n    # m of this program instance\n    # ####################################################################\n    # Note: cos and sin have shape (3, num_tokens, head_dim // 2)\n    # where the 3 dimensions are T, H, W sections\n\n    half_rd = rd // 2\n    # Base pointers for T, H, W sections for this token\n    t_cos = cos + pid * half_rd\n    h_cos = t_cos + num_tokens * half_rd\n    w_cos = h_cos + num_tokens * half_rd\n    t_sin = sin + pid * half_rd\n    h_sin = t_sin + num_tokens * half_rd\n    w_sin = h_sin + num_tokens * half_rd\n\n    cos_offsets = tl.arange(0, pad_hd // 2)\n\n    if not is_interleaved:\n        # Non-interleaved layout: [TTT...HHH...WWW]\n        t_end = mrope_section_t\n        h_end = t_end + mrope_section_h\n\n        # Masks for each section based on contiguous ranges\n        t_mask = cos_offsets < t_end\n        h_mask = (t_end <= cos_offsets) & (cos_offsets < h_end)\n        w_mask = (h_end <= cos_offsets) & (cos_offsets < half_rd)\n\n        # Load cos/sin for each section\n        t_cos_row = tl.load(t_cos + cos_offsets, mask=t_mask, other=0)\n        h_cos_row = tl.load(h_cos + cos_offsets, mask=h_mask, other=0)\n        w_cos_row = tl.load(w_cos + cos_offsets, mask=w_mask, other=0)\n        t_sin_row = tl.load(t_sin + cos_offsets, mask=t_mask, other=0)\n        h_sin_row = tl.load(h_sin + cos_offsets, mask=h_mask, other=0)\n        w_sin_row = tl.load(w_sin + cos_offsets, mask=w_mask, other=0)\n\n        # Combine sections\n        cos_row = t_cos_row + h_cos_row + w_cos_row\n        sin_row = t_sin_row + h_sin_row + w_sin_row\n    else:\n        # Interleaved layout: [THTHTH...WWW]\n        # Position i uses section (i % 3) at index (i // 3)\n        # T: positions 0,3,6,... (i % 3 == 0)\n        # H: positions 1,4,7,... (i % 3 == 1)\n        # W: positions 2,5,8,... (i % 3 == 2)\n        \n        # Compute section index for each offset\n        section_idx = cos_offsets // 3\n        \n        # Masks: check both section membership (mod 3) and bounds\n        t_mask = (cos_offsets % 3 == 0) & (section_idx < mrope_section_t)\n        h_mask = (cos_offsets % 3 == 1) & (section_idx < mrope_section_h)\n        w_mask = (cos_offsets % 3 == 2) & (section_idx < mrope_section_w)\n\n        # Load cos/sin for each section with stride-3 layout\n        # T values are at positions 0, 3, 6, ... in the section\n        t_cos_row = tl.load(t_cos + cos_offsets, mask=t_mask, other=0)\n        t_sin_row = tl.load(t_sin + cos_offsets, mask=t_mask, other=0)\n        # H values are at positions 1, 4, 7, ... in the section\n        h_cos_row = tl.load(h_cos + cos_offsets, mask=h_mask, other=0)\n        h_sin_row = tl.load(h_sin + cos_offsets, mask=h_mask, other=0)\n        # W values are at positions 2, 5, 8, ... in the section\n        w_cos_row = tl.load(w_cos + cos_offsets, mask=w_mask, other=0)\n        w_sin_row = tl.load(w_sin + cos_offsets, mask=w_mask, other=0)\n\n        # Combine sections\n        cos_row = t_cos_row + h_cos_row + w_cos_row\n        sin_row = t_sin_row + h_sin_row + w_sin_row\n\n    # ####################################################################\n    # Load the left and right half of q and k for the current\n    # program instance (i.e. for the current token) separately\n    # ####################################################################\n    # left half of the head\n    first_half_q_offsets = tl.arange(0, pad_n_qh)[:, None] * hd + tl.arange(\n        0, pad_hd // 2)[None, :]\n    first_half_k_offsets = tl.arange(0, pad_n_kh)[:, None] * hd + tl.arange(\n        0, pad_hd // 2)[None, :]\n    first_q_mask = (tl.arange(0, pad_n_qh)[:, None] < n_qh) & (tl.arange(\n        0, pad_hd // 2)[None, :] < rd // 2)\n    first_k_mask = (tl.arange(0, pad_n_kh)[:, None] < n_kh) & (tl.arange(\n        0, pad_hd // 2)[None, :] < rd // 2)\n\n    q_tile_1 = tl.load(q_ptr + first_half_q_offsets,\n                       mask=first_q_mask,\n                       other=0).to(sin_row.dtype)\n    k_tile_1 = tl.load(k_ptr + first_half_k_offsets,\n                       mask=first_k_mask,\n                       other=0).to(sin_row.dtype)\n\n    # right half of the head\n    second_half_q_offsets = first_half_q_offsets + (rd // 2)\n    second_half_k_offsets = first_half_k_offsets + (rd // 2)\n    second_q_mask = first_q_mask\n    second_k_mask = first_k_mask\n\n    q_tile_2 = tl.load(q_ptr + second_half_q_offsets,\n                       mask=second_q_mask,\n                       other=0).to(sin_row.dtype)\n    k_tile_2 = tl.load(k_ptr + second_half_k_offsets,\n                       mask=second_k_mask,\n                       other=0).to(sin_row.dtype)\n\n    # y = [x1, x2] * [cos, cos] + [-x2, x1] * [sin, sin]\n    # Since cos and sin are now half-size,\n    # we use the same cos_row and sin_row for both halves\n    new_q_tile_1 = q_tile_1 * cos_row - q_tile_2 * sin_row\n    tl.store(q_ptr + first_half_q_offsets, new_q_tile_1, mask=first_q_mask)\n    new_q_tile_2 = q_tile_2 * cos_row + q_tile_1 * sin_row\n    tl.store(q_ptr + second_half_q_offsets, new_q_tile_2, mask=second_q_mask)\n\n    new_k_tile_1 = k_tile_1 * cos_row - k_tile_2 * sin_row\n    tl.store(k_ptr + first_half_k_offsets, new_k_tile_1, mask=first_k_mask)\n    new_k_tile_2 = k_tile_2 * cos_row + k_tile_1 * sin_row\n    tl.store(k_ptr + second_half_k_offsets, new_k_tile_2, mask=second_k_mask)"
    }
}
JSONEOF"}

